29	gate_summary () {
30	    local L="$1" O="$2" R="$FORTRESS_HOME/ProjectFortress/TEST-RESULTS" f
31	    {
32	      printf '#suite\ttests\tfailures\terrors\tskipped\n'
33	      for f in "$R"/fast-*/TEST-*.txt "$R"/system-*/TEST-*.txt "$R"/TEST-*SpecDataJUTest.txt ; do
34	        [ -f "$f" ] || continue
35	        awk -v track="$(case "$(basename "$(dirname "$f")")" in TEST-RESULTS) echo specdata ;; *) basename "$(dirname "$f")" ;; esac)" -F'[ ,:]+' '
36	          /^Testsuite:/ { n = split($2, p, "."); s = p[n] }
37	          /^Tests run:/ { print track "/" s "\t" $3 "\t" $5 "\t" $7 "\t" $9 ; exit }' "$f"
38	      done | sort
39	      for f in compileAll testFast testSystem testSpecData ; do
40	        [ -f "$L/$f.txt" ] && grep -h '^BUILD \|^Total time:' "$L/$f.txt" | sed "s|^|# $f: |"
41	      done
42	      bash explorations/compile-ladder/rung-flat-tower/machine.sh "${3:-gate}" | sed 's|^|# machine |'
43	    } > "$O"
44	}
