46	gate_compare () {
47	    awk -F'\t' '
48	      function key(s) { sub("^system-[0-9]+/", "system/", s) ; return s }
49	      FNR == NR { if ($0 !~ /^#/ && NF == 5) base[key($1)] += $2 ; next }
50	      $0 !~ /^#/ && NF == 5 {
51	          k = key($1) ; seen[k] = 1 ; cur[k] += $2
52	          if ($3 + 0 > 0 || $4 + 0 > 0)              { print "RED\t" $1 "\t" $3 " failures, " $4 " errors" ; bad++ }
53	          if ($2 + 0 == 0)                           { print "EMPTY\t" $1 ; bad++ }
54	      }
55	      END { for (k in cur) if ((k in base) && cur[k] < base[k]) { print "COUNT DOWN\t" k "\t" base[k] " -> " cur[k] ; bad++ }
56	            for (s in base) if (!(s in seen)) { print "SUITE GONE\t" s "\t" base[s] " -> absent" ; bad++ }
57	            if (bad) exit 1 }' "$1" "$2"
58	}
