68	ladder_compare () {
69	    local B="$1" N="$2" key
70	    awk -F'\t' '
71	      function rank(p,   r) { r["parse"]=1; r["disambiguate"]=2; r["typecheck"]=3; r["codegen"]=4;
72	                              r["link"]=5; r["run"]=6; r["pass"]=7; return r[p] + 0 }
73	      FNR == NR { if (FNR > 1) b[$1 "/" $2] = $4 ; next }
74	      FNR > 1 {
75	          k = $1 "/" $2
76	          if (!(k in b))                  { print "NEW\t" k "\t" $4 ; next }
77	          if (rank($4) < rank(b[k]))      { print "DOWN\t" k "\t" b[k] " -> " $4 }
78	          else if (rank($4) > rank(b[k])) { print "UP\t" k "\t" b[k] " -> " $4 }
79	      }' "$B/ladder.tsv" "$N/ladder.tsv"
80	    tail -n +2 "$B/pass-list.txt" | cut -f1 | while IFS= read -r key ; do
81	        [ -n "$key" ] || continue
82	        if [ ! -f "$N/raw/$key.run" ] ; then printf 'MISSING\t%s\n' "$key" ; continue ; fi
83	        if ! diff -q <(ladder_filter "$B/raw/$key.run") <(ladder_filter "$N/raw/$key.run") >/dev/null ; then
84	            printf 'STDOUT\t%s\n' "$key"
85	            diff <(ladder_filter "$B/raw/$key.run") <(ladder_filter "$N/raw/$key.run") | sed 's/^/    /' | head -8
86	        fi
87	    done
88	}
